            x >= leftTop.x &&
            y >= leftTop.y &&
            x <= rightBottom.x &&
            y <= rightBottom.y
          ) {
            // тінь входить до цього джерела світла
            const currentLight = acm.find((current) => current.light === light);
          }
        });

